<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>All Employees</h1><p>Search and manage employee master data</p></div><a class="btn btn--primary" href="<?= url('/admin/employees/create') ?>">Add New</a></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Search Employee</label><input class="module-input" name="employee_search" value="<?= e($search) ?>" placeholder="Name or employee number"></div><button class="btn btn--secondary">Search</button></form><section class="module-card"><div class="module-card__body"><?php if(!$employees):?><div class="compact-empty"><h3>No Employees Found</h3></div><?php else:?><table class="data-table"><thead><tr><th>Employee No</th><th>Name</th><th>Role</th><th>Mobile</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($employees as$e):?><tr><td><?= e($e['employee_no']) ?></td><td><?= e($e['name']) ?></td><td><?= e($e['role']) ?></td><td><?= e($e['mobile']??'') ?></td><td><?= e($e['status']) ?></td><td><a class="btn btn--secondary" href="<?= url('/admin/employees/'.$e['id'].'/edit') ?>">Edit</a><form method="post" action="<?= url('/admin/employees/'.$e['id'].'/status') ?>" style="display:inline"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $e['status']==='active'?'inactive':'active' ?>"><button class="btn btn--secondary"><?= $e['status']==='active'?'Deactivate':'Activate' ?></button></form></td></tr><?php endforeach ?></tbody></table><?php endif ?></div></section></div></div></main>
